-- ==============================================================================
-- คำสั่ง SQL สำหรับอัปเดตและนำเข้าคลังยา 196 รายการบน Supabase Cloud
-- ตาราง: public.opd_drugs (ตรงตาม Form: Generic Name, Strength, Dosage Form, Trade Name, หน่วย, ราคาซื้อ, ราคาขาย, คงเหลือ, จุดเตือน, ลิ้นชัก)
-- ==============================================================================

-- 1. เพิ่มคอลัมน์ที่จำเป็นหากยังไม่มี
alter table public.opd_drugs add column if not exists strength text;
alter table public.opd_drugs add column if not exists dosage_form text;
alter table public.opd_drugs add column if not exists purchase_price numeric default 0;
alter table public.opd_drugs add column if not exists min_stock numeric default 10;
alter table public.opd_drugs add column if not exists drawer text;

-- 2. ลบข้อมูลยาตัวอย่างเดิมที่เคยทดสอบ (D1 - D11)
delete from public.opd_drugs where drug_id in ('D1','D2','D3','D4','D5','D6','D7','D8','D9','D10','D11');

-- 3. นำเข้าหรืออัปเดตข้อมูลยา 196 รายการจริง
on conflict (drug_id) do update set
  generic_name = excluded.generic_name,
  strength = excluded.strength,
  dosage_form = excluded.dosage_form,
  trade_name = excluded.trade_name,
  unit = excluded.unit,
  purchase_price = excluded.purchase_price,
  cost_price = excluded.cost_price,
  sale_price = excluded.sale_price,
  stock = excluded.stock,
  min_stock = excluded.min_stock,
  drawer = excluded.drawer,
  active = excluded.active,
  updated_at = timezone('utc'::text, now());
